    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchMember
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchMember = async function () {
    /* sdd-asis-lifecycle:begin fn_searchMember — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = (document.searchForm || { elements: [] });
    const vIsurCd = $c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "");
    if ($c.str.getByteLength(vIsurCd) == 0) {
        await $c.win.alert("발행기관코드를 입력하십시오.");
        $c.util.getComponent("ipt_isurCd").setValue("");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    } else {
        if (vIsurCd.substring(0, 1) === "#") {
            await $c.win.alert("임시발행기관코드는 신청할 수 없습니다.");
            $c.util.getComponent("ipt_isurCd").setValue("");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        } else {
            if (vIsurCd.length < 5) {
                await $c.win.alert("발행기관코드 5자리를 입력하십시오.");
                $c.util.getComponent("ipt_isurCd").setValue("");
                $c.util.getComponent("ipt_isurCd").focus();
                return false;
            } else {
                scwin.form_searchForm.action = "/register/register.do?method=searchMember";
                scwin.form_searchForm.target = "_self";
                await scwin.tx_fn_searchMember();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.enterEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.enterEvent = async function (e) {
    /* sdd-asis-lifecycle:begin fn_enterEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (e.keyCode == 13) {
        await scwin.searchMember();
        return false;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param newYn
 * @returns
 * @hidden N
*/
scwin.confirm = async function (newYn) {
    /* sdd-asis-lifecycle:begin fn_confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    if (newYn !== "N") {
        const width = 1260;
        const height = 900;
        const mtWidth = document.body.clientWidth;
        const mtHeight = document.body.clientHeight;
        const scX = 0;
        const scY = 0;
        const popX = scX + (mtWidth - width) / 2;
        const popY = scY + (mtHeight - height) / 2;
        let _previewWindow;
        _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/register/register.do?method=registerMemberView", unresolved: "nav:" + "/register/register.do?method=registerMemberView" }; })();
        const searchForm = (document.searchForm || { elements: [] });
        scwin.form_searchForm.action = "/register/register.do?method=registerMemberView";
        scwin.form_searchForm.target = "popRegisterMember";
    }
    /* sdd-asis-lifecycle:end */
};
